static_assert(sizeof(YY_BM) == 7200, "yin-yang sprite must be 7200 bytes");

// Out-of-bounds reads 0, so the caller can sample a rotated point without clamping it first.
static inline uint8_t yyBit(int x, int y) {
  if ((unsigned)x >= (unsigned)YY_W || (unsigned)y >= (unsigned)YY_W) return 0;
  int i = y * YY_W + x;
  return (YY_BM[i >> 3] >> (7 - (i & 7))) & 1;
}
